#!/usr/bin/env node
// scripts/verify-build-facts.mjs
//
// Verifies build-order content against PRIMARY-SOURCE facts in
// src/data/game-facts.json (generated by build-game-facts.mjs from aalises data).
//
// Checks (objective, source-independent — counter/strategy prose is NOT judged
// here; that needs context, see docs/SOURCES.md):
//   1. unit-age: no build references a unit whose real Age is later than targetAge.
//   2. villager rail is non-decreasing across steps.
//   3. a leading "+N →" delta equals this step's villagers minus the last count.
//   4. step `time`s are strictly increasing and the last one is not past durationMin.
//   5. targetAge equals the highest phase present, and phases appear in age order.
// These caught real errors in the July-2026 build audit (mislabeled counts,
// missing phase fields, a build whose deltas didn't reconcile).
//
// Exit 0 = clean; 1 = at least one violation (so it can gate CI/deploys).

import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import yaml from "js-yaml";

const FACTS = path.resolve("src/data/game-facts.json");
const BUILDS = path.resolve("src/content/build-orders");

const PHASE_RANK = { feudal: 1, castle: 2, imperial: 3 };
const mmssToSec = (t) => {
  const m = String(t).match(/^(\d+):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
};

// Structural (arithmetic/ordering) checks over a single build's steps.
function structuralViolations(file, data) {
  const out = [];
  const steps = data?.steps ?? [];

  // 2 + 3: villager rail non-decreasing; a leading "+N →" delta reconciles.
  // The delta check only fires when it is UNAMBIGUOUS: exactly one "+N" clause in
  // the step (multi-delta steps like "+2 → farms, +6 → wood" are skipped) AND the
  // immediately-preceding step also states a count (no re-task gap in between).
  let lastPop = null;
  let prevHadPop = false;
  for (const [i, s] of steps.entries()) {
    const enText = s.assign?.en ?? "";
    const plusClauses = enText.match(/\+\d+\s*(?:→|->)/g) ?? [];
    const lead = enText.match(/^\s*\+(\d+)\s*(?:→|->)/);
    if (s.villagers != null) {
      if (lastPop != null && s.villagers < lastPop) {
        out.push(`${file}: step ${i + 1} villagers ${s.villagers} < previous ${lastPop} (rail must not decrease).`);
      }
      if (lead && plusClauses.length === 1 && prevHadPop && lastPop != null) {
        const delta = s.villagers - lastPop;
        if (delta !== Number(lead[1])) {
          out.push(`${file}: step ${i + 1} says "+${lead[1]}" but villagers went ${lastPop}→${s.villagers} (delta ${delta}).`);
        }
      }
      lastPop = s.villagers;
      prevHadPop = true;
    } else {
      prevHadPop = false;
    }
  }

  // 4: times strictly increasing; last time within durationMin (+90s slack for the
  // trailing age-up that finishes after the last click).
  const times = steps.map((s) => s.time).filter(Boolean).map(mmssToSec);
  for (let i = 1; i < times.length; i++) {
    if (times[i] != null && times[i - 1] != null && times[i] <= times[i - 1]) {
      out.push(`${file}: step times not strictly increasing (${steps.map((s) => s.time).filter(Boolean).join(" → ")}).`);
      break;
    }
  }
  const lastTime = times.filter((t) => t != null).at(-1);
  if (lastTime != null && data.durationMin != null && lastTime > data.durationMin * 60 + 90) {
    out.push(`${file}: last step time ${lastTime}s exceeds durationMin ${data.durationMin}m (+90s slack).`);
  }

  // 5: targetAge == highest phase present; phases appear in non-descending age order.
  const phases = steps.map((s) => s.phase).filter(Boolean);
  let prevRank = 0;
  for (const p of phases) {
    if (PHASE_RANK[p] < prevRank) {
      out.push(`${file}: phase "${p}" appears after a later age (phases must be in dark→feudal→castle→imperial order).`);
      break;
    }
    prevRank = Math.max(prevRank, PHASE_RANK[p]);
  }
  // targetAge must not be LOWER than the highest phase reached (a build tagged
  // "feudal" that clicks Castle is mislabeled). A build may legitimately omit
  // phase fields and rely on the render-time transition heuristic, so absence is
  // not an error here — only a present phase that exceeds targetAge is.
  const maxPhase = phases.reduce((a, p) => (PHASE_RANK[p] > PHASE_RANK[a ?? ""] ? p : a), null);
  if (maxPhase && data.targetAge && PHASE_RANK[maxPhase] > (PHASE_RANK[data.targetAge] ?? 0)) {
    out.push(`${file}: targetAge is ${data.targetAge} but a step reaches ${maxPhase} (a later age).`);
  }
  return out;
}

async function run() {
  const facts = JSON.parse(await readFile(FACTS, "utf8"));
  const { ageRank, units } = facts;

  const files = (await readdir(BUILDS)).filter((f) => f.endsWith(".yaml") || f.endsWith(".yml"));
  const violations = [];
  let checked = 0;

  for (const file of files) {
    const raw = await readFile(path.join(BUILDS, file), "utf8");
    const data = yaml.load(raw);
    violations.push(...structuralViolations(file, data));
    const targetAge = data?.targetAge;
    if (!targetAge || !(targetAge in ageRank)) continue;
    checked++;
    const limit = ageRank[targetAge];
    const iconSlugs = new Set(
      (data?.steps ?? []).flatMap((s) => s.icons ?? []),
    );
    for (const slug of iconSlugs) {
      const unit = units[slug];
      if (!unit) continue;
      if (ageRank[unit.age] > limit) {
        violations.push(
          `${file}: "${slug}" is a ${unit.age}-age unit but the build targetAge is ${targetAge} ` +
            `(source: aalises units.csv).`,
        );
      }
    }
  }

  console.log(
    `Verified ${checked} build orders against game-facts.json (${Object.keys(units).length} sourced units).`,
  );
  if (violations.length) {
    console.error(`\n${violations.length} build-order violation(s):`);
    for (const v of violations) console.error(`  - ${v}`);
    process.exit(1);
  }
  console.log("No unit-age or structural violations. ✓");
}

run().catch((e) => {
  console.error(e.message);
  process.exit(1);
});
